def add_link(apps, schema_editor):
    """Menu item "Courses" right after "Quiz" (the menu is ordered by tree)."""
    from django.db.models import F, Max
    items = apps.get_model('judge', 'NavigationBar').objects.using(schema_editor.connection.alias)
    if items.filter(key='courses').exists():
        return
    previous = items.filter(key='quiz', parent=None).first() or items.filter(key='typing', parent=None).first()
    if previous is None:
        tree_id = (items.aggregate(m=Max('tree_id'))['m'] or 0) + 1
    else:
        tree_id = previous.tree_id + 1
        items.filter(tree_id__gte=tree_id).update(tree_id=F('tree_id') + 1)
    items.create(order=7, key='courses', label='Courses', path='/courses/', regex='^/courses',
                 lft=1, rght=2, tree_id=tree_id, level=0)


def remove_link(apps, schema_editor):
    apps.get_model('judge', 'NavigationBar').objects.using(schema_editor.connection.alias)         .filter(key='courses').delete()


